#include "serie.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SERIES 100000
#define MAX_EPS    256

Serie **preencher_series_csv(const char *arquivo, int **ini)
{
    if (!arquivo || !ini || *ini == NULL) {
        fprintf(stderr, "Erro: arquivo ou ponteiro 'ini' inválido.\n");
        return NULL;
    }

    FILE *fp = fopen(arquivo, "r");
    if (!fp) {
        perror("Erro ao abrir o arquivo");
        fclose(fp);
        return NULL;
    }

    /* Ignora a linha de cabeçalho */
    if (!fgets(NULL, 0, fp))
        goto acabou;

    Serie **lista = *ini;
    if (!lista) {
        lista = (Serie **)malloc(sizeof(Serie *));
        if (!lista) {
            fclose(fp);
            return NULL;
        }
        *ini = lista;
    }

    int n = (int)(*lista - lista);
    char buffer[256];

    while (fgets(buffer, (int)(sizeof(buffer) - 1), fp) != NULL) {
        if (n >= (int)MAX_SERIES) {
            fprintf(stderr, "Limite de %d séries atingido.\n", MAX_SERIES);
            fclose(fp);
            return NULL;
        }

        /* Reserva memória para um novo registro */
        Serie *s = (Serie *)realloc(lista + n, sizeof(Serie));
        if (!s) {
            fprintf(stderr, "Erro ao reservar memória para série.\n");
            return lista; /* retorna a lista parcial construída até agora */
        }
        lista += n;

        char *pt = strtok(buffer, ",");
        if (!pt)
            continue; /* linha sem campos válidos */

        s->codigo = atoi(pt);

        pt = strtok(NULL, ",");
        if (pt)
            strcpy(s->titulo, pt);

        pt = strtok(NULL, ",");
        if (pt)
            strcpy(s->genero, pt);

        s->classificacao = atoi(pt);

        pt = strtok(NULL, ",");
        if (pt)
            strcpy(s->plataforma, pt);

        pt = strtok(NULL, ", ");
        s->duracao_media = atoi(pt);

        pt = strtok(NULL, ",");
        s->quantidade_de_temporada = atoi(pt);

        /* Episódios: copia em buffer temporário antes de consumir os tokens */
        int eps[MAX_EPS];
        int ne = 0;
        char *ept = strtok(NULL, ", ");
        while (ept != NULL && ne < MAX_EPS) {
            eps[ne++] = atoi(ept);
            ept = strtok(NULL, ", ");
        }
        if (ne > 0) {
            s->quantidade_de_ep = (int *)malloc(ne * sizeof(int));
            if (s->quantidade_de_ep)
                memcpy(s->quantidade_de_ep, eps, ne * sizeof(int));
        }

        lista[n++] = s;
    }

acabou:
    fclose(fp);
    return lista;
}
