#include "serie.h"

/**
 * Catálogo que agrupa as séries carregadas.
 */
typedef struct {
    int                    total;
    Serie                  **serie;
} Catalogo;

/**
 * Inicializa um catálogo vazio.
 */
void catalogo_inicializar(Catalogo *cat);

/**
 * Libera toda a memória do catálogo.
 */
void catalogo_liberar(const Catalogo *cat);

/**
 * Adiciona uma série ao catálogo.
 * Retorna 1 se incluída, 0 se já existia, -1 em caso de erro.
 */
int catalogo_adicionar(const Catalogo *cat, const Serie *s);

/**
 * Busca uma série pelo código.
 * Se encontrada, *out recebe um ponteiro para ela dentro do catálogo.
 * Retorna 1 se localizada, 0 caso contrário.
 */
int catalogo_buscar(const Catalogo *cat, int codigo, Serie **out);

/**
 * Remove uma série pelo código.
 * Retorna 1 se removida, 0 se não encontrada.
 */
int catalogo_remover(const Catalogo *cat, int codigo);

/**
 * Retorna a quantidade de séries cadastradas.
 */
size_t catalogo_quantidade(const Catalogo *cat);

/**
 * Obtém um ponteiro para uma série já existente.
 * Use após consultar catalogo_buscar ou catalogo_encontrar.
 */
const Serie *catalogo_encontrar(const Catalogo *cat, int codigo);

#endif /* CATALOGO_H */
