#include "serie.h"
#include "catalogo.h"

int main(void)
{
    Serie **series = NULL;
    int idx = 0;

    /* Carrega as séries do CSV. O contador 'idx' ficará com a quantidade. */
    series = preencher_series_csv("streaming_db.csv", &idx);
    if (!series) {
        fprintf(stderr, "Falha ao carregar séries do CSV.\n");
        return 1;
    }

    Catalogo cat;
    catalogo_inicializar(&cat);

    for (int i = 0; i < idx; i++) {
        const Serie *s = &series[i];

        if (catalogo_adicionar(&cat, s) != 1) {
            fprintf(stderr, "Série %d duplicada ou erro ao adicionar.\n", s->codigo);
            continue;
        }

        printf("Adicionada: cod=%d  tit=\"%s\"  gen=\"%s\"\n",
               s->codigo, s->titulo, s->genero);
    }

    printf("Total de séries: %zu\n", catalogo_quantidade(&cat));

    /* Exemplo de busca */
    Serie *achada = NULL;
    if (catalogo_buscar(&cat, 123, achada) == 1) {
        const Serie *found = achada[0];
        printf("Encontrada: \"%s\" - \"%s\"\n", found->titulo, found->genero);
    }

    catalogo_liberar(&cat);
    return 0;
}
