/* Limite conservador para episódios extras numa linha. */
#define EP_MAX_LINE 256

Serie **preencher_series_csv(const char *arquivo, int **ini)
{
    if (!arquivo || !ini || *ini == NULL) {
        fprintf(stderr, "preencher_series_csv: parâmetros inválidos.\n");
