        pt = strtok(NULL, ", ");
        s->duracao_media = atoi(pt);

        pt = strtok(NULL, ",");
        s->quantidade_de_temporada = atoi(pt);

        /* Episódios: armazena em buffer temporário antes de consumir os tokens restantes */
        int eps[EP_MAX_LINE];
        int ne = 0;
        char *ept = strtok(NULL, ", ");
        while (ept != NULL && ne < EP_MAX_LINE) {
