    if (!string || tamanho <= 1)
        return;

    /* Desvincula stdin para impedir buffering automático */
    if (setbuf(stdin, NULL) != 0) {
        fprintf(stderr, "Erro ao preparar entrada: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
