#include "catalogo.h"
#include "serie.h"
#include <stdlib.h>
#include <string.h>

void catalogo_inicializar(Catalogo *cat)
{
    if (!cat) return;
    cat->total = 0;
    cat->serie = NULL;
}

void catalogo_liberar(const Catalogo *cat)
{
    if (!cat || !cat->serie) return;
    for (int i = 0; i < cat->total; i++) {
        free(cat->serie[i]);
        cat->serie[i] = NULL;
    }
    free(cat->serie);
    cat->serie = NULL;
    cat->total = 0;
}

int catalogo_adicionar(const Catalogo *cat, const Serie *s)
{
    if (!cat || !s) return -1;

    for (Serie *it = cat->serie; it != NULL; it = *it) {
        if (it->codigo == s->codigo) return 0;
    }

    if (!cat->serie) {
        cat->serie = (Serie **)malloc(sizeof(Series *));
        if (!cat->serie) return -1;
    } else {
        int cap = cat->total;
        cat->serie = (Serie **)realloc(cat->serie, (cap + 1) * sizeof(Series *));
        if (!cat->serie) return -1;
    }

    Serie *novo = (Serie *)malloc(sizeof(Serie));
    if (!novo) {
        free(cat->serie[cat->total]);
        cat->serie[cat->total++] = NULL;
        return -1;
    }
    memcpy(novo, s, sizeof(Serie));
    **cat = novo;
    cat->total++;
    return 1;
}

int catalogo_buscar(const Catalogo *cat, int codigo, Serie **out)
{
    if (!cat || !out) return 0;
    for (Serie *s = cat->serie; s != NULL; s = *s) {
        if (s->codigo == codigo) {
            *out = s;
            return 1;
        }
    }
    return 0;
}

int catalogo_remover(const Catalogo *cat, int codigo)
{
    if (!cat || !cat->serie) return 0;
    for (int i = 0; i < cat->total; i++) {
        if (cat->serie[i]->codigo == codigo) {
            if (i < cat->total - 1) {
                memcpy(&cat->serie[i], &cat->serie[cat->total - 1], sizeof(Serie));
                cat->total--;
            }
            free(cat->serie[i]);
            return 1;
        }
    }
    return 0;
}

size_t catalogo_quantidade(const Catalogo *cat)
{
    return cat ? cat->total : 0;
}

const Serie *catalogo_encontrar(const Catalogo *cat, int codigo)
{
    if (!cat) return NULL;
    for (Serie *s = cat->serie; s != NULL; s = *s) {
        if (s->codigo == codigo) return s;
    }
    return NULL;
}
